<script setup>
import {reactive,ref,computed,watch,onMounted,onUnmounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {appointmentService} from '../../services/appointments';import {useClinicContextStore} from '../../stores/clinicContext';import {useAppointmentStore} from '../../stores/appointments';import {clock,minutes,terminalStatuses} from '../../utils/appointmentDates';import FormErrors from '../ui/FormErrors.vue';import PatientForm from '../patients/PatientForm.vue';
const props=defineProps({appointment:Object,reschedule:Boolean});const context=useClinicContextStore(),store=useAppointmentStore(),route=useRoute(),router=useRouter();
const form=reactive({branch_id:props.appointment?.branch_id||Number(route.query.branch_id)||context.data.branch.id,patient_id:props.appointment?.patient_id||Number(route.query.patient_id)||'',doctor_id:props.appointment?.doctor_id||Number(route.query.doctor_id)||'',date:props.appointment?.starts_at.slice(0,10)||route.query.date||context.data.today,start_time:props.appointment?.starts_at.slice(11,16)||route.query.start_time||'',duration:props.appointment?minutes(props.appointment.ends_at.slice(11))-minutes(props.appointment.starts_at.slice(11)):30,appointment_type_id:props.appointment?.appointment_type_id||'',reason:props.appointment?.reason||'',notes:props.appointment?.notes||'',source:props.appointment?.source||'clinic',override_schedule:false,override_reason:''});
const options=ref(null),patient=ref(props.appointment?.patient||null),patients=ref([]),search=ref(''),slots=ref([]),slotInfo=ref(null),slotsBusy=ref(false),optionsBusy=ref(false),busy=ref(false),error=ref(null),slotError=ref(null),register=ref(false),typeName=ref('');let timer,slotVersion=0,searchVersion=0,optionVersion=0;
const locked=computed(()=>props.appointment&&(terminalStatuses.includes(props.appointment.status)||props.appointment.status==='in_consultation'));
const end=computed(()=>form.start_time?clock(minutes(form.start_time)+Number(form.duration)): '—');
async function loadOptions(){const version=++optionVersion;optionsBusy.value=true;error.value=null;try{const {data}=await appointmentService.options(form.branch_id);if(version!==optionVersion)return;options.value=data.data;store.options=data.data;if(!props.appointment && !options.value.initialized){form.duration=options.value.defaults?.default_duration||30;options.value.initialized=true;}if(form.doctor_id&&!options.value.doctors.some(d=>d.id===Number(form.doctor_id)))form.doctor_id='';}catch(e){if(version===optionVersion)error.value=e;}finally{if(version===optionVersion)optionsBusy.value=false;}}
async function findPatient(){const version=++searchVersion;try{const {data}=await appointmentService.patients({search:search.value});if(version===searchVersion)patients.value=data.data;}catch(e){if(version===searchVersion)error.value=e;}}
function searchPatient(){clearTimeout(timer);timer=setTimeout(findPatient,250);}
function selectPatient(p){patient.value=p;form.patient_id=p.id;patients.value=[];search.value='';}
async function available(){const version=++slotVersion;slots.value=[];slotInfo.value=null;slotError.value=null;if(!form.doctor_id||!form.date||!form.duration){slotsBusy.value=false;return;}slotsBusy.value=true;try{const {data}=await appointmentService.slots(form.doctor_id,{branch_id:form.branch_id,date:form.date,duration:form.duration,patient_id:form.patient_id||undefined,appointment_id:props.appointment?.id,walk_in:form.source==='walk_in'?1:0});if(version===slotVersion){slots.value=data.data;slotInfo.value=data.meta;}}catch(e){if(version===slotVersion)slotError.value=e;}finally{if(version===slotVersion)slotsBusy.value=false;}}
async function addType(){error.value=null;try{const {data}=await appointmentService.type({name:typeName.value,default_duration:Number(form.duration)});options.value.types.push(data.data);form.appointment_type_id=data.data.id;typeName.value='';}catch(e){error.value=e;}}
function typeChanged(){const type=options.value.types.find(t=>t.id===Number(form.appointment_type_id));if(type)form.duration=type.default_duration;}
async function save(){busy.value=true;error.value=null;try{const {data}=props.reschedule?await appointmentService.reschedule(props.appointment.id,{...form}):await appointmentService.save(props.appointment?.id,{...form});store.notice=props.reschedule?'Appointment rescheduled successfully.':props.appointment?'Appointment updated successfully.':'Appointment booked successfully.';await router.push({path:`/app/appointments/${data.data.id}`,query:{date:form.date,branch_id:String(form.branch_id)}});}catch(e){error.value=e;await available();}finally{busy.value=false;}}
watch(()=>form.branch_id,()=>{form.doctor_id='';form.start_time='';loadOptions();});watch(()=>[form.doctor_id,form.branch_id,form.date,form.duration,form.patient_id,form.source],available);
onMounted(async()=>{await loadOptions();if(form.patient_id&&!patient.value){try{const {data}=await appointmentService.patients({id:form.patient_id});if(data.data[0])selectPatient(data.data[0]);}catch(e){error.value=e;}}await available();});onUnmounted(()=>{clearTimeout(timer);slotVersion++;searchVersion++;optionVersion++;});
</script>
<template><div v-if="locked" class="clinic-panel">This appointment can no longer be edited or rescheduled.</div><template v-else><section v-if="register" class="appointment-registration"><div class="clinic-card-heading"><h2>Register New Patient</h2><button class="btn-secondary" @click="register=false">Back to appointment</button></div><PatientForm embedded @saved="selectPatient($event);register=false" @cancel="register=false"/></section><form v-else class="patient-form appointment-form" @submit.prevent="save"><FormErrors :error="error"/><button v-if="error&&!options" type="button" class="btn-secondary" @click="loadOptions">Reload booking options</button><section class="clinic-panel"><div class="patient-section-heading"><span>1</span><h2>Patient</h2></div><div v-if="patient" class="appointment-selected-patient"><div><strong>{{patient.full_name}}</strong><p>{{patient.patient_number}} · {{patient.phone || 'No phone recorded'}}</p></div><button v-if="!reschedule" type="button" class="btn-secondary" @click="patient=null;form.patient_id=''">Change patient</button></div><template v-else><label class="field mt-5">Search Existing Patient *<input v-model="search" type="search" placeholder="Patient name, ID, phone or email" @input="searchPatient" @focus="findPatient"></label><div class="appointment-patient-results"><button v-for="p in patients" :key="p.id" type="button" @click="selectPatient(p)"><strong>{{p.full_name}}</strong><small>{{p.patient_number}} · {{p.phone}}</small></button><p v-if="search&&!patients.length" class="hint">No matching active patients.</p></div></template><button v-if="!reschedule&&context.allowed('patients')&&context.can('patients.create')" class="btn-secondary mt-4" type="button" @click="register=true">＋ Register New Patient</button></section><section class="clinic-panel"><div class="patient-section-heading"><span>2</span><h2>Clinician &amp; appointment time</h2></div><div class="patient-form-grid"><label class="field">Branch *<select aria-label="Branch *" v-model="form.branch_id" required><option v-for="b in context.data.branches" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label class="field">Doctor *<select aria-label="Doctor *" v-model="form.doctor_id" required :disabled="optionsBusy"><option value="">{{optionsBusy?'Loading clinicians…':'Select a clinician'}}</option><option v-for="d in options?.doctors" :key="d.id" :value="d.id">{{d.full_name}}</option></select></label><label class="field">Date *<input v-model="form.date" type="date" required></label><label class="field">Duration (minutes) *<input v-model="form.duration" type="number" min="5" max="480" step="1" required></label><label class="field">Start time *<select aria-label="Start time *" v-if="!form.override_schedule" v-model="form.start_time" required :disabled="slotsBusy"><option value="">Select an available time</option><option v-if="form.start_time&&!slots.includes(form.start_time)" :value="form.start_time" disabled>{{form.start_time}} — unavailable</option><option v-for="time in slots" :key="time" :value="time">{{time}}</option></select><input v-else v-model="form.start_time" type="time" required></label><label class="field">End time<output class="appointment-end">{{end}}</output></label></div><p class="hint mt-4">All times are in {{context.data.clinic.timezone}}. Slots respect working hours, breaks, leave and existing appointments.</p><FormErrors :error="slotError"/><button v-if="slotError" type="button" class="btn-secondary mt-3" @click="available">Retry available times</button><p v-if="slotsBusy" class="hint mt-3" role="status">Checking available times…</p><div v-else-if="form.doctor_id&&!slots.length&&slotInfo?.message" class="appointment-slot-notice" role="status"><p>{{slotInfo.message}}</p><div class="flex flex-wrap gap-3 mt-3"><RouterLink v-if="['schedule_missing','non_working_day','clinician_unavailable'].includes(slotInfo.reason_code)&&context.allowed('doctors')&&context.can('doctors.schedule.view')" class="btn-secondary" :to="{path:`/app/doctors/${form.doctor_id}/schedule`,query:{branch_id:form.branch_id}}" target="_blank" rel="noopener">{{context.can('doctors.schedule.update')?'Set working hours':'View working hours'}} ↗</RouterLink><button class="btn-secondary" type="button" @click="available">Refresh available times</button></div><p v-if="slotInfo.reason_code==='schedule_missing'" class="hint mt-3">Choose working days and start/end times, then save the schedule. Return here and refresh available times.</p></div><div v-else class="appointment-slot-picker"><button v-for="time in slots" :key="time" type="button" :class="form.start_time===time?'btn':'btn-secondary'" @click="form.start_time=time">{{time}}</button></div><details v-if="context.can('appointments.override_schedule')" class="mt-5"><summary class="text-sm text-teal-700 cursor-pointer">Schedule override</summary><label class="doctor-day mt-4"><input v-model="form.override_schedule" type="checkbox">Allow a time outside working hours or during a break</label><label v-if="form.override_schedule" class="field mt-4">Override reason *<input v-model="form.override_reason" required maxlength="500"></label><p class="hint mt-3">Leave, inactive clinicians, and booking conflicts still block the appointment.</p></details></section><section v-if="!reschedule" class="clinic-panel"><div class="patient-section-heading"><span>3</span><h2>Visit details</h2></div><div class="patient-form-grid"><label class="field">Appointment type<select aria-label="Appointment type" v-model="form.appointment_type_id" @change="typeChanged"><option value="">Select type (optional)</option><option v-for="t in options?.types" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label class="field">Appointment source<select aria-label="Appointment source" v-model="form.source"><option value="clinic">Clinic</option><option value="phone">Phone</option><option value="online">Online</option><option v-if="options?.defaults?.allow_walk_in !== false" value="walk_in">Walk-in</option></select></label><div v-if="context.can('appointments.types.manage')" class="col-span-full flex flex-wrap gap-3"><input v-model="typeName" class="filter-input" aria-label="New appointment type" placeholder="New visit type name" maxlength="100"><button class="btn-secondary" type="button" :disabled="!typeName.trim()||!options" @click="addType">Add Type</button></div><label class="field col-span-full">Reason<textarea v-model="form.reason" rows="2" maxlength="2000"></textarea></label><label class="field col-span-full">Notes<textarea v-model="form.notes" rows="3" maxlength="5000"></textarea></label></div><p class="hint mt-4">{{form.source==='walk_in'?'Walk-ins enter the waiting queue.':'New appointments are scheduled by default.'}}</p></section><div class="sticky-actions"><RouterLink class="btn-secondary" to="/app/appointments">Cancel</RouterLink><button class="btn" :disabled="busy||optionsBusy||slotsBusy||!patient||!form.start_time||(!form.override_schedule&&!slots.includes(form.start_time))">{{busy?'Saving…':reschedule?'Save Reschedule':appointment?'Save Changes':'Book Appointment'}}</button></div></form></template></template>
